package app.bikriflow.mobile.data
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
class Repository(private val db: AppDatabase) { suspend fun products(query: String = "") = withContext(Dispatchers.IO) { db.getProducts(query) }; suspend fun saveProduct(product: Product) = withContext(Dispatchers.IO) { db.upsertProduct(product) }; suspend fun archiveProduct(id: Long) = withContext(Dispatchers.IO) { db.archiveProduct(id) }; suspend fun orders(query: String = "", status: OrderStatus? = null) = withContext(Dispatchers.IO) { db.getOrders(query, status) }; suspend fun order(id: Long) = withContext(Dispatchers.IO) { db.getOrder(id) }; suspend fun createOrder(order: Order) = withContext(Dispatchers.IO) { db.createOrder(order) }; suspend fun updateStatus(id: Long, status: OrderStatus) = withContext(Dispatchers.IO) { db.updateOrderStatus(id, status) }; suspend fun dashboard() = withContext(Dispatchers.IO) { db.dashboardMetrics() }; suspend fun customers() = withContext(Dispatchers.IO) { db.getCustomerSummaries() } }
